import java.io.Console;

public class _1599_C {
    public static void main(String[] args) {
        Console console = System.console();
        if (console == null) {
            System.err.println("No console");
            return;
        }
        String[] tokens = console.readLine().split(" ");
        int n = Integer.parseInt(tokens[0]);
        double p = Double.parseDouble(tokens[1]);
        int total = chooseThree(n);
        int i = 0;
        while (i <= n) {
            double prob = 0;
            double p1 = (double) i * chooseTwo(n - i) / total;
            double p2 = (double) chooseTwo(i) * (n - i) / total;
            double p3 = (double) chooseThree(i) / total;
            prob = p1 / 2 + p2 + p3;
            if (prob >= p) {
                console.printf("%d%n", i);
                break;
            }
            i++;
        }
    }
    static int chooseTwo(int n) {
        if (n < 2) return 0;
        return n * (n - 1) / 2;
    }
    static int chooseThree(int n) {
        if (n < 3) return 0;
        return n * (n - 1) * (n - 2) / 6;
    }
}
